[CmdletBinding()]
param([Parameter(Mandatory=$true)][string]$ConfigurationPath)
$ErrorActionPreference='Stop'
function Absolute([string]$Value){return $Value -match '^(?:[A-Za-z]:[\\/]|\\\\[^\\/]+[\\/][^\\/]+[\\/])' -and $Value -notmatch '[\0\r\n]'}
function Inside([string]$Root,[string]$Candidate){$prefix=$Root.TrimEnd('\')+'\';return $Candidate.Equals($Root,[StringComparison]::OrdinalIgnoreCase)-or $Candidate.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)}
function Assert-NoReparseSegments([string]$Candidate){$cursor=[IO.Path]::GetFullPath($Candidate);$segments=New-Object Collections.Generic.List[string];while(-not[string]::IsNullOrWhiteSpace($cursor)){$segments.Add($cursor);$parent=Split-Path -Parent $cursor;if([string]::IsNullOrWhiteSpace($parent)-or$parent-ceq$cursor){break};$cursor=$parent};foreach($segment in @($segments|Sort-Object{$_.Length})){if(Test-Path -LiteralPath $segment){$item=Get-Item -LiteralPath $segment -Force;if(($item.Attributes-band[IO.FileAttributes]::ReparsePoint)-ne0){throw 'Provider-host validation paths cannot traverse a reparse point.'}}}}
function Exact-Keys($Value,[string[]]$Required,[string[]]$Optional=@()){$names=@($Value.PSObject.Properties.Name);$allowed=@($Required+$Optional);return @($Required|Where-Object{$_ -notin $names}).Count -eq 0 -and @($names|Where-Object{$_ -notin $allowed}).Count -eq 0}
function Regular([string]$Path){if(-not(Test-Path -LiteralPath $Path -PathType Leaf)){return $false};return ((Get-Item -LiteralPath $Path -Force).Attributes -band [IO.FileAttributes]::ReparsePoint) -eq 0}
function Sha([string]$Path){$stream=[IO.File]::OpenRead($Path);$hasher=[Security.Cryptography.SHA256]::Create();try{return ([BitConverter]::ToString($hasher.ComputeHash($stream))).Replace('-','').ToLowerInvariant()}finally{$hasher.Dispose();$stream.Dispose()}}
function Sid([string]$Identity){return ([Security.Principal.NTAccount]$Identity).Translate([Security.Principal.SecurityIdentifier]).Value}
function Protected-Acl([string[]]$Paths){$current=[Security.Principal.WindowsIdentity]::GetCurrent().User.Value;$allowed=@($current,'S-1-5-18');foreach($path in $Paths){$acl=Get-Acl -LiteralPath $path;if((Sid ([string]$acl.Owner)) -cne $current){return $false};if($path -ceq $Paths[0] -and -not $acl.AreAccessRulesProtected){return $false};$hasCurrent=$false;foreach($rule in @($acl.Access)){if($rule.AccessControlType -ne [Security.AccessControl.AccessControlType]::Allow){continue};$sid=$rule.IdentityReference.Translate([Security.Principal.SecurityIdentifier]).Value;if($sid -notin $allowed){return $false};if($sid -ceq $current){$hasCurrent=$true}};if(-not $hasCurrent){return $false}};return $true}
function Envelope([string]$Path){if(-not(Regular $Path)){return $false};try{$value=Get-Content -LiteralPath $Path -Raw|ConvertFrom-Json;return (Exact-Keys $value @('schema','version','protector','sealed')) -and $value.schema -ceq 'sxsy-b122.provider-host-secret-envelope' -and $value.version -eq 1 -and $value.protector -ceq 'windows-dpapi-current-user' -and [string]$value.sealed -cmatch '^[A-Za-z0-9+/]+={0,2}$' -and ([string]$value.sealed).Length -le 32768}catch{return $false}}
function Assert-KeyRoleSeparation([string[]]$Paths){
  Add-Type -AssemblyName System.Security|Out-Null;$keys=New-Object Collections.Generic.List[object]
  try{
    foreach($secretPath in $Paths){$envelope=Get-Content -LiteralPath $secretPath -Raw|ConvertFrom-Json;$sealed=$null;$clear=$null;try{$sealed=[Convert]::FromBase64String([string]$envelope.sealed);$clear=[Security.Cryptography.ProtectedData]::Unprotect($sealed,$null,[Security.Cryptography.DataProtectionScope]::CurrentUser);if($clear.Length-ne64){throw 'A provider-host authentication key is not exactly 256 canonical bits.'};foreach($byte in $clear){if(-not(($byte-ge48-and$byte-le57)-or($byte-ge97-and$byte-le102))){throw 'A provider-host authentication key is not canonical lowercase hexadecimal.'}};$keys.Add([pscustomobject]@{Bytes=$clear});$clear=$null}finally{if($null-ne$sealed){[Array]::Clear($sealed,0,$sealed.Length)};if($null-ne$clear){[Array]::Clear($clear,0,$clear.Length)}}}
    for($leftIndex=0;$leftIndex-lt$keys.Count;$leftIndex++){for($rightIndex=$leftIndex+1;$rightIndex-lt$keys.Count;$rightIndex++){$left=[byte[]]$keys[$leftIndex].Bytes;$right=[byte[]]$keys[$rightIndex].Bytes;$difference=0;for($offset=0;$offset-lt64;$offset++){$difference=$difference-bor($left[$offset]-bxor$right[$offset])};if($difference-eq0){throw 'Provider-host bearer, journal, and dispatch-lease authentication keys must be cryptographically independent.'}}}
  }finally{foreach($entry in $keys){$bytes=[byte[]]$entry.Bytes;[Array]::Clear($bytes,0,$bytes.Length)}}
}
function Tls-Identity([string]$CertificatePath,[string]$PrivateKeyPath) {$helperCandidates=@((Join-Path $PSScriptRoot 'Get-B122TlsIdentity.mjs'),(Join-Path $PSScriptRoot '..\Get-B122TlsIdentity.mjs'));$helper=@($helperCandidates|Where-Object{Test-Path -LiteralPath $_ -PathType Leaf})[0];if(-not $helper){throw 'The provider-host TLS identity inspector is missing.'};$bundledNode=Join-Path $PSScriptRoot '..\..\runtime\node.exe';$node=if(Test-Path -LiteralPath $bundledNode -PathType Leaf){[IO.Path]::GetFullPath($bundledNode)}else{(Get-Command node.exe -ErrorAction Stop).Source};$identity=& $node $helper --certificate $CertificatePath --private-key $PrivateKeyPath|ConvertFrom-Json;if($LASTEXITCODE -ne 0 -or $identity.schema -cne 'sxsy-b122.tls-identity' -or $identity.version -ne 1 -or $identity.certificateAuthority -ne $false -or $identity.serverAuthentication -ne $true -or $identity.loopbackIdentity -ne $true -or $identity.validNow -ne $true -or $identity.privateKeyMatches -ne $true){throw 'The provider-host TLS identity could not be verified.'};return $identity}

$path=[IO.Path]::GetFullPath($ConfigurationPath);if(-not(Regular $path)){throw 'The provider-host configuration is missing or is a reparse point.'}
$config=Get-Content -LiteralPath $path -Raw|ConvertFrom-Json
if(-not(Exact-Keys $config @('schema','version','protectedStateRoot','listen','tls','authenticationTokenEnvelopeFile','journalAuthenticationEnvelopeFile','dispatchLeaseAuthenticationEnvelopeFile','stateFile','providers') @('allowFixtureBackends','effectDrivers')) -or $config.schema -cne 'sxsy-b122.provider-host-config' -or $config.version -ne 1 -or -not(Exact-Keys $config.listen @('host','port')) -or $config.listen.host -cnotin @('127.0.0.1','::1') -or -not(Exact-Keys $config.tls @('certificateFile','privateKeyFile','certificateSha256','privateKeySha256','tlsSpkiSha256')) -or [string]$config.tls.certificateSha256 -cnotmatch '^[a-f0-9]{64}$' -or [string]$config.tls.privateKeySha256 -cnotmatch '^[a-f0-9]{64}$' -or [string]$config.tls.tlsSpkiSha256 -cnotmatch '^[a-f0-9]{64}$'){throw 'The provider-host configuration schema, loopback listener, or TLS pins are invalid.'}
$root=[IO.Path]::GetFullPath([string]$config.protectedStateRoot);$local=[Environment]::GetFolderPath('LocalApplicationData');$base=[IO.Path]::GetFullPath((Join-Path $local 'STRATHEX\switchyard\provider-host'))
if(-not(Inside $base $root) -or -not(Inside $root $path)){throw 'The provider-host configuration escaped its dedicated protected current-user root.'}
foreach($owned in @([string]$config.tls.privateKeyFile,[string]$config.authenticationTokenEnvelopeFile,[string]$config.journalAuthenticationEnvelopeFile,[string]$config.dispatchLeaseAuthenticationEnvelopeFile,[string]$config.stateFile)){if(-not(Absolute $owned) -or -not(Inside $root ([IO.Path]::GetFullPath($owned)))){throw 'A provider-host private key, secret, or state path escaped ProtectedStateRoot.'}}
if(-not(Absolute ([string]$config.tls.certificateFile))){throw 'The provider-host TLS certificate path is not absolute.'}
foreach($candidate in @($base,$root,$path,[string]$config.tls.certificateFile,[string]$config.tls.privateKeyFile,[string]$config.authenticationTokenEnvelopeFile,[string]$config.journalAuthenticationEnvelopeFile,[string]$config.dispatchLeaseAuthenticationEnvelopeFile,[string]$config.stateFile)){Assert-NoReparseSegments $candidate}
if(-not(Absolute ([string]$config.tls.certificateFile)) -or -not(Regular ([string]$config.tls.certificateFile)) -or -not(Regular ([string]$config.tls.privateKeyFile)) -or (Sha ([string]$config.tls.certificateFile)) -cne [string]$config.tls.certificateSha256 -or (Sha ([string]$config.tls.privateKeyFile)) -cne [string]$config.tls.privateKeySha256){throw 'The provider-host TLS material does not match its reviewed pins.'}
if(-not(Envelope ([string]$config.authenticationTokenEnvelopeFile))){throw 'The provider-host authentication token is not a DPAPI CurrentUser envelope.'}
if(-not(Envelope ([string]$config.journalAuthenticationEnvelopeFile))){throw 'The provider-host journal authentication key is not a DPAPI CurrentUser envelope.'}
if(-not(Envelope ([string]$config.dispatchLeaseAuthenticationEnvelopeFile))){throw 'The provider-host dispatch-lease authentication key is not a DPAPI CurrentUser envelope.'}
Assert-KeyRoleSeparation @([string]$config.authenticationTokenEnvelopeFile,[string]$config.journalAuthenticationEnvelopeFile,[string]$config.dispatchLeaseAuthenticationEnvelopeFile)
$tlsIdentity=Tls-Identity ([string]$config.tls.certificateFile) ([string]$config.tls.privateKeyFile);if([string]$tlsIdentity.certificateFileSha256 -cne [string]$config.tls.certificateSha256 -or [string]$tlsIdentity.privateKeyFileSha256 -cne [string]$config.tls.privateKeySha256 -or [string]$tlsIdentity.tlsSpkiSha256 -cne [string]$config.tls.tlsSpkiSha256){throw 'The provider-host TLS certificate and private-key identity do not match their reviewed pins.'}
$providers=@($config.providers);if($providers.Count -lt 1 -or $providers.Count -gt 2){throw 'The provider-host configuration has an invalid provider count.'}
$seen=@{};$providerModules=@{};$fixtureOnly=$true;$credentialReferences=0;$credentialEnvelopesPresent=0;$protectedFiles=New-Object Collections.Generic.List[string];$protectedFiles.Add($path);$protectedFiles.Add([string]$config.tls.privateKeyFile);$protectedFiles.Add([string]$config.authenticationTokenEnvelopeFile);$protectedFiles.Add([string]$config.journalAuthenticationEnvelopeFile);$protectedFiles.Add([string]$config.dispatchLeaseAuthenticationEnvelopeFile)
foreach($entry in $providers){
  if($entry.provider -cnotin @('claude','codex') -or $entry.kind -cnotin @('fixture','module') -or $seen.ContainsKey([string]$entry.provider)){throw 'The provider-host configuration has an invalid or duplicate provider.'};$seen[[string]$entry.provider]=$true
  if($entry.kind -ceq 'fixture'){if(-not(Exact-Keys $entry @('provider','kind')) -or $config.allowFixtureBackends -ne $true -or $config.listen.host -cnotin @('127.0.0.1','::1')){throw 'A provider fixture is not explicitly loopback-authorized.'};continue}
  $fixtureOnly=$false
  if(-not(Exact-Keys $entry @('provider','kind','modulePath','moduleSha256','credentialEnvelopeFile') @('options')) -or -not(Absolute ([string]$entry.modulePath)) -or -not(Absolute ([string]$entry.credentialEnvelopeFile)) -or -not(Inside $root ([IO.Path]::GetFullPath([string]$entry.credentialEnvelopeFile))) -or [string]$entry.moduleSha256 -cnotmatch '^[a-f0-9]{64}$'){throw 'A configured provider module or protected credential envelope reference is invalid.'}
  Assert-NoReparseSegments ([string]$entry.modulePath);Assert-NoReparseSegments ([string]$entry.credentialEnvelopeFile)
  if(-not(Regular ([string]$entry.modulePath)) -or (Sha ([string]$entry.modulePath)) -cne [string]$entry.moduleSha256){throw 'A configured provider module or protected credential envelope reference is invalid.'}
  $credentialReferences+=1;if(Envelope ([string]$entry.credentialEnvelopeFile)){$credentialEnvelopesPresent+=1;$protectedFiles.Add([string]$entry.credentialEnvelopeFile)};$providerModules[[string]$entry.provider]=$entry
}
$effectDrivers=@();if(@($config.PSObject.Properties.Name)-contains'effectDrivers'){$effectDrivers=@($config.effectDrivers)};if($effectDrivers.Count-gt2){throw 'The provider-host configuration contains too many host effect drivers.'};$seenDrivers=@{}
foreach($entry in $effectDrivers){
  if(-not(Exact-Keys $entry @('provider','kind','modulePath','moduleSha256')) -or $entry.provider-cnotin@('claude','codex') -or $entry.kind-cne'module' -or $seenDrivers.ContainsKey([string]$entry.provider) -or -not(Absolute ([string]$entry.modulePath)) -or [string]$entry.moduleSha256-cnotmatch'^[a-f0-9]{64}$'){throw 'A configured host effect driver has an invalid or broadened identity.'}
  $seenDrivers[[string]$entry.provider]=$true;$provider=$providerModules[[string]$entry.provider];if($null-eq$provider){throw 'A configured host effect driver lacks its exact module provider identity.'}
  Assert-NoReparseSegments ([string]$entry.modulePath)
  if(-not(Regular ([string]$entry.modulePath)) -or (Sha ([string]$entry.modulePath))-cne[string]$entry.moduleSha256 -or [IO.Path]::GetFullPath([string]$entry.modulePath)-ceq[IO.Path]::GetFullPath([string]$provider.modulePath) -or [string]$entry.moduleSha256-ceq[string]$provider.moduleSha256){throw 'A configured host effect driver is missing, tampered, or not independently pinned.'}
}
if(-not(Protected-Acl (@($root)+@($protectedFiles)))){throw 'Provider-host protected storage is not restricted to the current Windows user and SYSTEM.'}
$tokenPresent=Envelope ([string]$config.authenticationTokenEnvelopeFile);$credentialsPresent=$credentialReferences -eq $credentialEnvelopesPresent
$journalPresent=Envelope ([string]$config.journalAuthenticationEnvelopeFile)
$dispatchLeasePresent=Envelope ([string]$config.dispatchLeaseAuthenticationEnvelopeFile)
[ordered]@{schema='sxsy-b122.provider-host-configuration-validation';version=1;status='passed';configurationSha256=(Sha $path);protectedStateRoot=$root;providerCount=$providers.Count;effectDriverCount=$effectDrivers.Count;mediatedConfigurationPresent=($effectDrivers.Count-gt0);fixtureOnly=$fixtureOnly;authenticationTokenEnvelopePresent=$tokenPresent;journalAuthenticationEnvelopePresent=$journalPresent;dispatchLeaseAuthenticationEnvelopePresent=$dispatchLeasePresent;authenticationKeyRolesDistinct=$true;credentialReferences=$credentialReferences;credentialEnvelopesPresent=$credentialEnvelopesPresent;startReady=($tokenPresent -and $journalPresent -and $dispatchLeasePresent -and $credentialsPresent);cleartextCredentialRead=$false;protectedAcl=$true}|ConvertTo-Json -Compress
